}

function ctx.SlotLimit(): number
	local bonus = if player:GetAttribute("Pass_ExtraSlots") then GameConfig.ExtraSlotsBonus else 0
	return GameConfig.BaseCreatureSlots + bonus
end

Hud.Init(ctx)
Panels.Init(ctx)
Cinematics.Init(ctx)

