	local card = group(UIKit.panel({ Name = "CreatureCard", AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromScale(0.008, 0.45), Size = yy(230, 128), Parent = gui }), 84)
	scalePadding(card, 0.06)
